using Intranet.Entity;
using Intranet.Service;
namespace Intranet.Api.Tests;
public sealed class AnalisisRbRequotationTests {
 private static AnalisisRbSave Request(decimal price,decimal rate,decimal final,bool enabled=true)=>new(){RequestId=Guid.NewGuid(),Source=new("J1825",217,1.404m,11.51m),UsedTime=11.51m,ServicePrice=final,OtherExpenses=.03m,Requotation=new(enabled,price,rate)};
 [Theory][InlineData(10,.10,1)][InlineData(10,.07,.7)][InlineData(1.30,.80,1.04)][InlineData(3,.3333333333333333,1)][InlineData(0,.1,0)]public void UsesDecimalMultiplierDirectly(decimal price,decimal rate,decimal final){var snapshot=AnalisisRbHistoryService.BuildSnapshot(Request(price,rate,final),DateTime.Today);Assert.True(snapshot.Requotation!.Enabled);Assert.Equal(price,snapshot.Requotation.BaseServicePrice);Assert.Equal(rate,snapshot.Requotation.Percentage);Assert.Equal(final,snapshot.ServicePrice);Assert.Equal(final+.03m,snapshot.Calculated.ServiceWithExpenses);}
 [Fact]public void PersistsUncheckedStateWithoutHiddenValues(){var result=AnalisisRbHistoryService.BuildSnapshot(Request(10,.1m,8,false),DateTime.Today);var restored=System.Text.Json.JsonSerializer.Deserialize<AnalisisRbSnapshot>(System.Text.Json.JsonSerializer.Serialize(result));Assert.False(restored!.Requotation!.Enabled);Assert.Null(restored.Requotation.BaseServicePrice);Assert.Null(restored.Requotation.Percentage);Assert.Equal(8,restored.ServicePrice);}
 [Fact]public void DiscardsStaleUncheckedValuesBeforeValidation(){var request=Request(10,.1m,8,false);request.Requotation=new(false,999999999m,-99m);var result=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.False(result.Requotation!.Enabled);Assert.Null(result.Requotation.BaseServicePrice);Assert.Null(result.Requotation.Percentage);}
 [Fact]public void RejectsInconsistentProduct(){Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(Request(10,.1m,10),DateTime.Today));}
 [Theory][InlineData(-1,.1)][InlineData(10,-.1)]public void RejectsNegativeActiveInputs(decimal price,decimal rate){Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(Request(price,rate,1),DateTime.Today));}
 [Fact]public void RequiresActiveFields(){var request=Request(10,.1m,1);request.Requotation=new(true,null,.1m);Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));request.Requotation=new(true,10,null);Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));}
 [Fact]public void OldRequestsWithoutOptionKeepWorking(){var request=Request(10,.1m,1);request.Requotation=null;Assert.Null(AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today).Requotation);}
 [Fact]public void WorksTogetherWithPartialSelection(){var request=Request(10,.1m,1);request.UsedTime=.65m;request.PartialSelection=new("99863","0","CS","COSTURA",11.51m,[new("948","PANTALON","001","369595","0","UNIR",.65m)]);var snapshot=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.True(snapshot.Requotation!.Enabled);Assert.NotNull(snapshot.PartialSelection);Assert.Equal("TIEMPO PARCIAL",snapshot.Calculated.TimeLabel);}
}
